from pathlib import Path
import re,html,json,subprocess,textwrap
p=Path('output/lab3/CEG3536_Lab3_Arikan_Zuze/preuves/materiel').resolve()
def make(name,title,body,source):
 body=re.sub(r'\x1b\[[0-9;]*[A-Za-z]','',body).strip()
 height=max(650,300+24*len(body.splitlines()))
 doc='<!doctype html><meta charset="utf-8"><style>body{font:20px Arial;padding:35px;background:#eff3f7;color:#183b56}pre{font:17px/24px monospace;background:#142333;color:white;padding:22px;white-space:pre-wrap}footer{font-size:14px}</style><h1>'+html.escape(title)+'</h1><p>STM32L552 réel - 10 novembre 2026 - preuve matérielle</p><pre>'+html.escape(body)+'</pre><footer>Capture d’une vue des sorties authentiques enregistrées : '+html.escape(source)+'. Journaux bruts conservés.</footer>'
 f=p/(name+'.html');f.write_text(doc)
 if '--capture' in __import__('sys').argv:
  subprocess.run(['/usr/bin/google-chrome','--headless','--no-sandbox','--disable-gpu','--disable-background-networking','--no-first-run','--hide-scrollbars','--user-data-dir=/tmp/lab3_hw_captures',f'--screenshot={p/name}.png',f'--window-size=1300,{height}',f.as_uri()],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,check=True)
 print(name)
make('H1_connexion','Connexion et programmation vérifiées',(p/'connexion_nouvel_essai.log').read_text()+'\n'+ '\n'.join(re.sub(r'\x1b\[[0-9;]*[A-Za-z]','',(p/'flash_O0.log').read_text()).splitlines()[-12:]),'connexion_nouvel_essai.log ; flash_O0.log')
make('H2_telemetrie','T1 / T9 - télémétrie réelle, 30 secondes','\n'.join((p/'serie_reelle_30s.csv').read_text().splitlines()[:7])+'\n\n'+(p/'validation_serie_reelle.log').read_text(),'serie_reelle_30s.csv ; validation_serie_reelle.log')
g=(p/'gdb_aapcs_O0.log').read_text();make('H3_aapcs','T2 - registres et pile sur STM32',g[g.index('=== T2'):g.index('=== T3')],'gdb_aapcs_O0.log (partie achevée avant correction du type GDB)')
make('H4_vitesse_registres','T3 / T4 - calculs et périphériques',(p/'gdb_vitesse_registres_O0.log').read_text(),'gdb_vitesse_registres_O0.log')
s=(p/'diagnostic_O0.csv').read_text(errors='replace');selected=[l for l in s.splitlines() if l.startswith(('Q,','B,','A,','Z,','T,19337','T,19538'))];make('H5_diagnostics_O0','T7 / T10 - file et comparaison ASM/C à -O0','\n'.join(selected)+'\n\nCCR1 ASM et C : [0, 2, 50, 100, 150, 198, 200, 200]\nTableaux vérifiés en mémoire dans gdb_initial_O0.log.','diagnostic_O0.csv ; gdb_initial_O0.log')
s=(p/'maximum_et_banc_O2.csv').read_text(errors='replace');make('H6_diagnostics_O2','T4 / T10 - maximum et benchmark à -O2','\n'.join(l for l in s.splitlines() if l.startswith(('A,','B,')))+'\n\n'+(p/'verification_flash_O2.txt').read_text(),'maximum_et_banc_O2.csv ; verification_flash_O2.txt')
s=(p/'milieu_O2.csv').read_text(errors='replace');make('H7_adc_dma','T4 - milieu et débit DMA','\n'.join(l for l in s.splitlines() if l.startswith('A,'))+'\n\nTrois commandes a espacées de 2 s.\nTours : 3030 -> 3126 -> 3222 ; 64 paires par tour.\nDébit estimé : 96 × 64 / 2 = 3072 échantillons/s/voie.\nAttendu : 3062,79 ; écart estimé +0,30 %.\nMesure sur 2 s, incertitude de phase et de lecture du compteur.','milieu_O2.csv ; milieu_O2.timestamps.json')
make('H8_estop','T8 - coupure réelle déclenchée par E-Stop',(p/'estop_declenchement_physique.log').read_text()+'\n\nPB2=1 ; PE15/STB=0 ; TIM1_CCR1=0 ; estop_flag=1.\nLe point d’arrêt survient après la coupure ISR.\nCette capture ne mesure pas la latence <1 ms.','estop_declenchement_physique.log')
make('H9_correctif_encodeur','Correction du pilote et régression sur STM32',(p/'correctif_encodeur.md').read_text()+'\n'+(p/'regression_encodeur_corrige.log').read_text(),'correctif_encodeur.md ; regression_encodeur_corrige.log')
make('H10_acquittement','T8 - acquittement explicite par Touch En',(p/'diagnostic_touch.log').read_text()+'\n\nTest isole : E-Stop presse puis relache, sans Touch En.\nEtat urgence maintenu jusqu’au nouvel appui Touch En.\nPB2 relache, PB5 actif ; passage etat3/flag1 -> etat0/flag0.\nAucune remise en marche automatique observee.','diagnostic_touch.log ; essais_physiques.csv')
make('H11_telemetrie_finale','T9 - image finale : 150 trames, 5,00 Hz',(p/'validation_finale_O2.log').read_text()+'\n'+(p/'serie_finale_O2_selection.txt').read_text(),'serie_finale_O2_30s.csv ; validation_finale_O2.log')
make('H12_estop_100','T8 - E-Stop à 100 % et intégrité des trames',(p/'validation_trames_estop.log').read_text()+'\n\nExtrait reel couvrant ticks128000..133000, meme demarrage final O2.\nLa latence electrique <1ms ne peut pas etre deduite de la trame a5Hz.','estop_100pct_trames.csv ; validation_trames_estop.log')
s=(p/'temperature_externe_avec_fil.csv').read_text(errors='replace');a=[l for l in s.splitlines() if l.startswith('A,temp_')];t=(p/'retour_interne.csv').read_text(errors='replace');b=[l for l in t.splitlines() if l.startswith('A,temp_')];make('H13_temperature_ext','T6 - comparaison externe non validée','EXT, pont declare installe (configuration non verifiee en photo) :\n'+'\n'.join(a)+'\n\nRETOUR INT :\n'+'\n'.join(b)+'\n\nExt ~1,01-1,03V : lecture incompatible avec un pont direct fonctionnel.\nInt ~1,82V : temperature plausible ~26C.\nNe pas ajuster la calibration pour masquer ce defaut de raccordement.','temperature_externe_avec_fil.csv ; retour_interne.csv')
body=(p/'etat_final.log').read_text()+'\n'+ '\n'.join((p/'cubeide_final.log').read_text().splitlines()[-4:]);make('H14_etat_final','Etat final et construction STM32CubeIDE',body,'etat_final.log ; cubeide_final.log')
